-- Generated by Supabase CLI; normalized to this repository's forward prefix.
-- Publication delegates an admin's upload; it never transfers media ownership,
-- copies bytes, clears moderation, or weakens authenticated post_media policies.
BEGIN;
CREATE TABLE public.official_post_media_commands (
 actor_id uuid NOT NULL REFERENCES public.profiles(id) ON DELETE CASCADE,
 operation_id uuid NOT NULL,
 intent_hash text NOT NULL,
 post_id uuid NOT NULL,
 media_asset_ids uuid[] NOT NULL DEFAULT '{}',
 created_at timestamptz NOT NULL DEFAULT now(),
 PRIMARY KEY(actor_id,operation_id)
);
CREATE INDEX official_post_media_commands_post_idx ON public.official_post_media_commands(post_id);
ALTER TABLE public.official_post_media_commands ENABLE ROW LEVEL SECURITY;
REVOKE ALL ON public.official_post_media_commands FROM PUBLIC,anon,authenticated;
GRANT SELECT,INSERT ON public.official_post_media_commands TO service_role;

CREATE FUNCTION public.create_official_post_with_media(
 p_actor_id uuid, p_operation_id uuid, p_fields jsonb,
 p_upload_paths text[] DEFAULT '{}', p_external_refs text[] DEFAULT '{}'
) RETURNS jsonb LANGUAGE plpgsql SECURITY INVOKER SET search_path=pg_catalog,public AS $$
DECLARE
 official_id uuid; new_id uuid; fingerprint text; prior public.official_post_media_commands%ROWTYPE;
 asset public.media_assets%ROWTYPE; assets uuid[]='{}'; current_path text; poster text; ordinal integer=0;
 schedule_at timestamptz; published public.posts%ROWTYPE; contains_video boolean=false;
BEGIN
 IF p_actor_id IS NULL OR p_operation_id IS NULL OR jsonb_typeof(p_fields) IS DISTINCT FROM 'object'
   OR p_upload_paths IS NULL OR p_external_refs IS NULL
   OR cardinality(p_upload_paths)+cardinality(p_external_refs)>10 THEN RAISE EXCEPTION 'official_post_invalid'; END IF;
 -- Re-read privileges in the command transaction; requireAdmin is not a stale
 -- role receipt. Service role is the only SQL caller; actor comes from auth.
 PERFORM 1 FROM public.profiles WHERE id=p_actor_id AND role='admin' AND coalesce(account_status,'active')='active' FOR SHARE;
 IF NOT FOUND THEN RAISE EXCEPTION 'official_post_forbidden'; END IF;
 IF EXISTS(SELECT 1 FROM public.user_account_states WHERE user_id=p_actor_id AND state IN ('banned','suspended') AND (expires_at IS NULL OR expires_at>now())) THEN
   RAISE EXCEPTION 'official_post_forbidden';
 END IF;
 SELECT id INTO STRICT official_id FROM public.profiles WHERE handle='portava' AND is_official=true FOR SHARE;
 fingerprint=encode(sha256(convert_to(jsonb_build_object('fields',p_fields,'uploads',p_upload_paths,'external',p_external_refs)::text,'UTF8')),'hex');
 PERFORM pg_advisory_xact_lock(hashtextextended(p_actor_id::text||':'||p_operation_id::text,0));
 SELECT * INTO prior FROM public.official_post_media_commands WHERE actor_id=p_actor_id AND operation_id=p_operation_id;
 IF FOUND THEN
  IF prior.intent_hash<>fingerprint THEN RAISE EXCEPTION 'official_post_intent_conflict'; END IF;
  SELECT * INTO published FROM public.posts WHERE id=prior.post_id AND author_id=official_id AND deleted_at IS NULL AND status='active';
  IF NOT FOUND THEN RAISE EXCEPTION 'official_post_unavailable'; END IF;
  RETURN jsonb_build_object('post',to_jsonb(published),'replayed',true);
 END IF;
 IF EXISTS(SELECT 1 FROM jsonb_object_keys(p_fields) k WHERE k NOT IN ('content','category','visibility','scheduledAt','locationName','locationCity','locationCountry','locationLat','locationLng'))
  OR length(btrim(coalesce(p_fields->>'content','')))=0 OR length(p_fields->>'content')>3000
  OR coalesce(p_fields->>'visibility','public') NOT IN ('public','private')
  OR coalesce(length(p_fields->>'locationName'),0)>200 OR coalesce(length(p_fields->>'locationCity'),0)>100 OR coalesce(length(p_fields->>'locationCountry'),0)>100
  OR coalesce(length(p_fields->>'category'),0)>100 THEN RAISE EXCEPTION 'official_post_invalid'; END IF;
 IF p_fields->>'locationLat' IS NOT NULL AND NOT ((p_fields->>'locationLat')::numeric BETWEEN -90 AND 90) THEN RAISE EXCEPTION 'official_post_invalid'; END IF;
 IF p_fields->>'locationLng' IS NOT NULL AND NOT ((p_fields->>'locationLng')::numeric BETWEEN -180 AND 180) THEN RAISE EXCEPTION 'official_post_invalid'; END IF;
 schedule_at=(p_fields->>'scheduledAt')::timestamptz;
 IF schedule_at IS NOT NULL AND schedule_at<=now() THEN RAISE EXCEPTION 'official_post_invalid'; END IF;
 IF EXISTS(SELECT 1 FROM unnest(p_external_refs) ref WHERE ref IS NULL OR length(ref)>2048 OR ref !~ '^https?://[^[:space:]]+$' OR ref ~* '(storage/v1/object/|post-media/)') THEN RAISE EXCEPTION 'official_post_invalid'; END IF;
 IF cardinality(p_upload_paths)<>(SELECT count(DISTINCT path) FROM unnest(p_upload_paths) path) THEN RAISE EXCEPTION 'official_post_invalid'; END IF;
 new_id=gen_random_uuid();
 INSERT INTO public.posts(id,author_id,created_by,updated_by,content,category,media_urls,visibility,status,source,post_status,
  publish_after_time,publish_eligible_at,published_at,location_name,location_city,location_country,location_lat,location_lng,
  public_location_label,location_source,location_verified,location_privacy_mode,location_sensitivity_level,add_to_passport,geofence_radius_meters,publish_after_exit,geotag_verified,geotag_credit_awarded)
 VALUES(new_id,official_id,p_actor_id,p_actor_id,p_fields->>'content',p_fields->>'category',p_external_refs,
  coalesce(p_fields->>'visibility','public')::public.post_visibility,'active','admin_portava',
  (CASE WHEN schedule_at IS NULL THEN 'published' ELSE 'pending_delay' END)::public.delayed_post_status,
  schedule_at,schedule_at,CASE WHEN schedule_at IS NULL THEN now() ELSE NULL END,p_fields->>'locationName',p_fields->>'locationCity',p_fields->>'locationCountry',
  (p_fields->>'locationLat')::numeric,(p_fields->>'locationLng')::numeric,coalesce(p_fields->>'locationCity',p_fields->>'locationName'),
  'manual',false,'city_only','low',false,150,false,false,false);
 FOREACH current_path IN ARRAY p_upload_paths LOOP
  IF split_part(current_path,'/',1)<>p_actor_id::text OR current_path ~ '(^|/)\.\.(/|$)|[%?#\\]' THEN RAISE EXCEPTION 'official_media_not_owned'; END IF;
  SELECT * INTO STRICT asset FROM public.media_assets WHERE storage_bucket='post-media' AND storage_path=current_path FOR SHARE;
  IF asset.owner_user_id<>p_actor_id OR asset.deleted_at IS NOT NULL OR asset.purge_status IS DISTINCT FROM 'not_requested'
   OR asset.processing_status<>'ready' OR asset.moderation_status NOT IN ('pending','approved','active')
   OR NOT EXISTS(SELECT 1 FROM storage.objects WHERE bucket_id='post-media' AND name=current_path)
   OR EXISTS(SELECT 1 FROM public.post_media_moderation_ledger WHERE storage_path=current_path) THEN RAISE EXCEPTION 'official_media_unavailable'; END IF;
  poster=NULL;
  IF asset.media_type='video' AND asset.thumbnail_path=current_path||'.poster.jpg'
    AND EXISTS(SELECT 1 FROM storage.objects WHERE bucket_id='post-media' AND name=asset.thumbnail_path)
    AND NOT EXISTS(SELECT 1 FROM public.post_media_moderation_ledger WHERE storage_path=asset.thumbnail_path) THEN poster=asset.thumbnail_path; END IF;
  INSERT INTO public.post_media(post_id,user_id,media_type,storage_bucket,storage_path,public_url,mime_type,file_size_bytes,width,height,duration_seconds,processing_status,moderation_status,sort_order,thumbnail_storage_path,thumbnail_url)
  VALUES(new_id,p_actor_id,asset.media_type,'post-media',current_path,'post-media/'||current_path,asset.mime_type,asset.size_bytes,asset.width,asset.height,
    asset.duration_ms/1000.0,'ready','pending',ordinal,poster,CASE WHEN poster IS NULL THEN NULL ELSE 'post-media/'||poster END);
  INSERT INTO public.media_attachments(media_asset_id,entity_type,entity_id,position,is_cover) VALUES(asset.id,'post',new_id,ordinal,ordinal=0);
  assets=array_append(assets,asset.id); ordinal=ordinal+1; contains_video=contains_video OR asset.media_type='video';
 END LOOP;
 UPDATE public.posts SET media_count=ordinal,has_video=contains_video,
  primary_media_type=CASE WHEN ordinal=0 THEN NULL WHEN contains_video THEN 'video' ELSE 'image' END,
  media_type=CASE WHEN ordinal=0 THEN NULL WHEN contains_video THEN 'video' ELSE 'image' END
 WHERE id=new_id RETURNING * INTO published;
 INSERT INTO public.official_post_media_commands(actor_id,operation_id,intent_hash,post_id,media_asset_ids) VALUES(p_actor_id,p_operation_id,fingerprint,new_id,assets);
 RETURN jsonb_build_object('post',to_jsonb(published),'replayed',false);
END;
$$;
REVOKE ALL ON FUNCTION public.create_official_post_with_media(uuid,uuid,jsonb,text[],text[]) FROM PUBLIC,anon,authenticated;
GRANT EXECUTE ON FUNCTION public.create_official_post_with_media(uuid,uuid,jsonb,text[],text[]) TO service_role;
COMMENT ON TABLE public.official_post_media_commands IS 'Audited admin delegation of owned canonical uploads into an official post, committed atomically with post_media and media_attachments. The original owner may still withdraw their media. No copied media or ownership transfer. Durable command identity prevents retry resurrection after post deletion.';
COMMIT;
